<?php
namespace App\Http\Resources;
use Illuminate\Http\Request;
use Illuminate\Http\Resources\Json\JsonResource;
final class ReportResource extends JsonResource { public function toArray(Request $request): array { return ['id'=>$this->id,'reference'=>$this->reference,'title'=>$this->title,'description'=>$this->description,'location_text'=>$this->location_text,'latitude'=>$this->latitude,'longitude'=>$this->longitude,'status'=>$this->status,'submitted_at'=>$this->submitted_at?->toIso8601String(),'created_at'=>$this->created_at?->toIso8601String(),'category'=>$this->whenLoaded('category',fn()=>['id'=>$this->category->id,'name'=>$this->category->name]),'barangay'=>$this->whenLoaded('barangay',fn()=>['id'=>$this->barangay->id,'name'=>$this->barangay->name]),'attachments'=>$this->whenLoaded('attachments',fn()=>$this->attachments->map(fn($item)=>['id'=>$item->id,'name'=>$item->original_name,'mime_type'=>$item->mime_type,'size'=>$item->size,'download_url'=>route('api.v1.reports.attachments.show',[$this->id,$item->id],false)])),'timeline'=>$this->whenLoaded('statusHistory',fn()=>$this->statusHistory->map(fn($item)=>['id'=>$item->id,'from_status'=>$item->from_status,'status'=>$item->to_status,'note'=>$item->note,'actor'=>$item->actor?->name,'created_at'=>$item->created_at?->toIso8601String()])),'updates'=>$this->whenLoaded('updates',fn()=>$this->updates->map(fn($item)=>['id'=>$item->id,'body'=>$item->body,'author'=>$item->author?->name,'created_at'=>$item->created_at?->toIso8601String()])),'assignment'=>$this->whenLoaded('assignments',fn()=>optional($this->assignments->firstWhere('is_active',true),fn($item)=>['officer'=>$item->assignee?->name,'barangay_id'=>$item->barangay_id,'department_id'=>$item->department_id])),'resolution'=>$this->whenLoaded('resolution',fn()=>optional($this->resolution,fn($item)=>['notes'=>$item->notes,'resolved_at'=>$item->resolved_at?->toIso8601String(),'evidence_url'=>$item->evidence_path?route('api.v1.reports.resolution-evidence.show',$this->id,false):null,'resident_rating'=>$item->resident_rating,'resident_feedback'=>$item->resident_feedback]))]; } }
